def _alns_budget_progress(self, alns_start_ms, reserve):
    usable_budget_s = max(0.0, self.time_limit - float(reserve))
    if usable_budget_s <= 0.0:
        return 1.0
    elapsed_s = max(
        0.0,
        (self.context.elapsed_ms() - alns_start_ms) / 1000.0,
    )
    return min(1.0, elapsed_s / usable_budget_s)

def _remaining_time_ms(self):
    remaining_time_ms = getattr(self.context, "remaining_time_ms", None)

class _SimulatedAnnealing:
    def __init__(self, initial_cost, start_ratio=0.05, end_ratio=0.0001):
        base = max(float(initial_cost), 1.0)
        self.start_temp = max(base * start_ratio, 1e-9)
        self.end_temp = max(base * end_ratio, 1e-12)
        self.temperature = self.start_temp

    def accept(self, current_cost, candidate_cost, rng, *, progress=0.0):
        self.set_progress(progress)
        delta = float(candidate_cost) - float(current_cost)
        if delta <= 0:
            return True
        if self.temperature <= 0:
            return False
        return rng.random() < math.exp(-delta / self.temperature)

    def set_progress(self, progress):
        progress = min(1.0, max(0.0, float(progress)))
        ratio = self.end_temp / self.start_temp
        self.temperature = max(
            self.end_temp,
            min(
                self.start_temp,
                self.start_temp * (ratio ** progress),
            ),
        )

